import {writeDecisionGuides} from './decision-guides.mjs';
import {writeAcademicGuides} from './academic-guides.mjs';
import fs from 'node:fs';
import path from 'node:path';
import {iconifyHTML} from '../src/icons.mjs';
import {getCourseSpecs} from '../src/course-specs.mjs';
import {courses,areas,articles,events,services,faqs,portalNav} from '../src/data.mjs';
import {loadSchool,createBrand,paletteCss} from './school.mjs';
import {loadNavigation,loadHeader,loadFooter,loadSite,loadSimplePages,loadPageHeads,loadNotices,loadHome,loadInstitutionalPage,renderHeadline,renderInline} from './content.mjs';
const school=loadSchool();
// A validação em school.mjs recusa & < > " ' no nome, no país e na moeda:
// por isso um valor da configuração pode ser inserido depois de esc() sem reescapar.
const brand=createBrand(school);
const navigation=loadNavigation();
const site={header:loadHeader(),footer:loadFooter(),...loadSite()};
// Ênfase do conteúdo: *assim* → <em>assim</em>, sempre depois de esc(), e uma
// linha do conteúdo por quebra no título. O conteúdo nunca traz marcação.
const headline=value=>renderHeadline(value,esc);
// Toda a cadeia de navegação vem do conteúdo: rótulo, caminho interno validado
// e a seta de saída como sinalizador, não como texto escrito à mão.
const navAnchor=({url,label,external})=>`<a href="${esc(url)}">${esc(label)}${external?' ↗':''}</a>`;
const sigaPortal=school.portal;
const out='dist';fs.mkdirSync(out,{recursive:true});fs.cpSync('public',out,{recursive:true});fs.mkdirSync(out+'/integration',{recursive:true});fs.copyFileSync('integration/client.mjs',out+'/integration/client.mjs');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const logo=`<svg viewBox="0 0 36 36" aria-hidden="true"><path d="M5 12 18 5l13 7-13 7zM5 19l13 7 13-7M5 26l13 7 13-7"/></svg><span>{{SCHOOL}}<span class="brand-dot">.</span></span>`;
// O href do SIGA vive na página /login/, que NÃO é uma página do portal. A versão
// anterior fazia esta substituição sob o sinalizador de layout `portal`, que ali é
// sempre falso — o portalUrl configurado nunca chegava a nenhuma página.
const withSigaPortal=html=>sigaPortal?html.replace('href="/signin-with-chatgpt?return_to=%2Fportal%2F"',()=>`href="${esc(sigaPortal.href)}"`).replace('Entrar com ChatGPT','Entrar no SIGA Plus'):html;
const link=(url,label,style='button')=>`<a class="${style}" href="${url}">${label}<span aria-hidden="true">↗</span></a>`;
const notice=(text=site.notice)=>`<div class="notice"><span aria-hidden="true">ⓘ</span><p>${text}</p></div>`;
const notices=loadNotices();
const noticeFor=key=>{const text=notices.get(key);if(!text)throw Error('Aviso em falta em content/notices.json: '+key);return esc(text)};
const crumb=(title,extra='')=>`<div class="breadcrumb wrap"><a href="/">${esc(site.breadcrumbHome)}</a><span>/</span>${extra}<span>${esc(title)}</span></div>`;
function menu({title,feature,links}){return `<details class="nav-dropdown"><summary>${esc(title)}<span>⌄</span></summary><div class="mega-menu"><div class="menu-highlight"><span class="eyebrow">O SEU PRÓXIMO PASSO</span><h3>${esc(feature.title)}</h3><p>${esc(feature.text)}</p>${link(esc(feature.url),esc(feature.label),'text-link')}</div><div class="mega-links">${links.map(({url,label,sub})=>`<a href="${esc(url)}"><strong>${esc(label)} <span>↗</span></strong><small>${esc(sub)}</small></a>`).join('')}</div></div></details>`}
function header(){const {skipLink,homeLabel,navLabel,menuLabel,topline,links,search,portal}=site.header;return `<a class="skip-link" href="#main">${esc(skipLink)}</a><div class="topline"><div class="wrap"><span>${esc(topline.identity)} <i></i> ${esc(topline.tagline)}</span><div>${topline.links.map(navAnchor).join('')}</div></div></div><header class="site-header"><div class="header-inner wrap"><a class="brand" href="/" aria-label="${esc(homeLabel)}">${logo}</a><button class="mobile-toggle icon-button" aria-expanded="false" aria-controls="main-nav" aria-label="${esc(menuLabel)}">☰</button><nav id="main-nav" aria-label="${esc(navLabel)}">${navigation.map(menu).join('')}${links.map(l=>`<a class="simple-nav" href="${esc(l.url)}">${esc(l.label)}</a>`).join('')}<div class="mobile-actions"><a href="${esc(portal.url)}">${esc(portal.mobileLabel)} ↗</a></div></nav><div class="header-actions"><a class="header-search" href="${esc(search.url)}" aria-label="${esc(search.label)}"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/></svg></a><a class="button small" href="${esc(portal.url)}">${esc(portal.label)} <span>↗</span></a></div></div></header>`}
function footer(){const {tagline,locale,columns,notice,copyright,legal,backToTop}=site.footer;return `<footer class="site-footer"><div class="wrap"><div class="footer-main"><div><a class="brand" href="/">${logo}</a><p>${tagline.map(esc).join('<br>')}</p><span class="locale">◎ ${esc(locale)}</span></div>${columns.map(c=>`<div><h3>${esc(c.title)}</h3>${c.links.map(navAnchor).join('')}</div>`).join('')}</div><div class="footer-demo">${esc(notice)}</div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${esc(copyright)}</span><div>${legal.map(navAnchor).join('')}</div><a href="#top">${esc(backToTop)} ↑</a></div></div></footer>`}
const routes=[];const searchContent=new Map();
function write(url,title,body,{portal=false,description,active=''}={}){const html=`<!doctype html><html lang="{{LANG}}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="${esc(school.themeColor)}"><meta name="description" content="${esc(description||title+' '+site.meta.descriptionSuffix)}"><title>${esc(title)} | ${esc(site.meta.titleSuffix)}</title><link rel="icon" href="/assets/icon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;450;500;550;600;650;700&family=Manrope:wght@400;500;600;650;700;750;800&display=swap" rel="stylesheet"><link href="/style.css" rel="stylesheet"></head><body id="top" data-page="${esc(active||url)}" class="${portal?'portal-body':''}">${portal?'':header()}${portal?body:`<main id="main">${body}</main>${footer()}`}<div id="toast" role="status" aria-live="polite"></div><dialog id="site-dialog"><button class="dialog-close icon-button" aria-label="Fechar janela">×</button><div id="dialog-content"></div></dialog><script type="module" src="/app.js"></script></body></html>`;const dir=path.join(out,url);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),iconifyHTML(brand(withSigaPortal(html))));routes.push({url,title});searchContent.set(url,body.replace(/<[^>]*>/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/\s+/g,' ').trim().slice(0,12000))}
function pageHead(label,title,desc,extra=''){return `<section class="page-head"><div class="wrap"><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p>${extra}</div><span class="head-spark" aria-hidden="true">✳</span></section>`}
// Cada página vai buscar o seu cabeçalho pela rota. Uma rota sem entrada no
// conteúdo pára o build: é a mesma regra das chaves em falta, ao nível da página.
const pageHeads=loadPageHeads();
const home=loadHome();
// Uma página institucional por ficheiro em content/pages/, validada pela forma
// declarada em content.mjs.
const pagina=name=>loadInstitutionalPage(name);
// Texto corrido: os parágrafos trazem ligações na convenção [rótulo](/caminho/),
// convertidas depois de esc(), e a lista de referências sai do mesmo bloco.
const prose=name=>{const page=pagina(name);write('/'+name+'/',page.title,`${crumb(page.crumb)}${head('/'+name+'/')}<article class="prose wrap section">${page.sections.map(s=>`<h2>${esc(s.title)}</h2>${s.paragraphs.map(t=>`<p>${renderInline(t,esc)}</p>`).join('')}${s.links?`<ul>${s.links.map(l=>`<li><a href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.label)}</a>: ${esc(l.text)}</li>`).join('')}</ul>`:''}`).join('')}</article>`)};
// Os artigos em destaque de uma página são escolhidos pelo conteúdo: um id que
// não exista em data.mjs pára o build, em vez de desenhar uma grelha vazia.
const articleList=ids=>ids.map(id=>{const a=articles.find(x=>x.id===id);if(!a)throw Error('Artigo em falta em src/data.mjs: '+id);return a});
const head=(route,extra='')=>{const h=pageHeads.get(route);if(!h)throw Error('Página sem cabeçalho em content/page-heads.json: '+route);return pageHead(esc(h.eyebrow),headline(h.headline),esc(h.description),extra)};
function courseCard(c){const area=areas.find(a=>a.id===c.area);return `<article class="course-card" data-course="${c.id}"><div class="course-img ${area.color}"><a href="/cursos/${c.id}/" tabindex="-1" aria-hidden="true"><img src="/assets/${c.image}.webp" alt="" loading="lazy"></a><span class="pill">${c.level}</span><button class="favorite-button" data-favorite="${c.id}" aria-label="Guardar ${c.name} nos favoritos" aria-pressed="false">♡</button></div><div class="course-content"><span class="eyebrow course-area-label"><i class="area-dot ${area.color}"></i>${area.name}</span><h3><a href="/cursos/${c.id}/">${c.name}</a></h3><p>${c.description}</p><div class="course-meta"><span>◷ ${c.duration}</span><span>◎ ${c.mode}</span><span>☷ ${c.shift}</span></div><div class="course-actions"><a href="/cursos/${c.id}/">Conhecer o curso <span>↗</span></a><label><input type="checkbox" data-compare="${c.id}"> Comparar</label></div></div></article>`}
const searchBox=(id='hero-search')=>`<form class="course-search" action="/cursos/" id="${id}"><div><span aria-hidden="true">⌕</span><label class="sr-only" for="${id}-q">Nome ou área do curso</label><input id="${id}-q" name="q" placeholder="O que quer aprender?" type="search"></div><label class="sr-only" for="${id}-level">Nível de formação</label><select id="${id}-level" name="nivel"><option value="">Todas as formações</option><option>Licenciatura</option><option>Pós-graduação</option><option>Curso de curta duração</option></select><button class="button" type="submit">Encontrar curso <span>↗</span></button></form>`;
const cta=()=>`<section class="cta wrap reveal"><div><span class="eyebrow">${esc(site.cta.eyebrow)}</span><h2>${headline(site.cta.title)}</h2><p>${esc(site.cta.text)}</p></div><div>${link(esc(site.cta.primary.url),esc(site.cta.primary.label))}${link(esc(site.cta.secondary.url),esc(site.cta.secondary.label),'text-link')}</div><span class="cta-star" aria-hidden="true">✳</span></section>`;
write('/',home.title,`<section class="home-hero wrap"><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> ${esc(home.hero.eyebrow)}</div><h1>${headline(home.hero.headline)}<span class="hero-arrow">↗</span></h1><p>${headline(home.hero.text)}</p><div class="hero-buttons">${link(esc(home.hero.primary.url),esc(home.hero.primary.label))}${link(esc(home.hero.secondary.url),esc(home.hero.secondary.label),'text-link')}</div><div class="hero-small"><span class="mini-symbol">✳</span><span>${headline(home.hero.small)}</span></div></div><div class="hero-visual"><div class="hero-grid"></div><div class="hero-photo"><img src="/assets/hero.webp" alt="${esc(home.hero.photoAlt)}" fetchpriority="high"><div class="hero-photo-caption">${esc(home.hero.photoCaption)} <span>↗</span></div></div><div class="hero-float"><span>✳</span><p>${headline(home.hero.float)}</p></div><div class="hero-badge"><i></i> ${esc(home.hero.badge)}</div><span class="hero-spark">✳</span><span class="hero-side">${esc(home.hero.side)}</span></div></section><section class="finder wrap"><div class="finder-title"><span class="eyebrow">${esc(home.finder.eyebrow)}</span>${navAnchor(home.finder.link)}</div>${searchBox()}<div class="finder-tags"><span>${esc(home.finder.tagsLabel)}</span>${home.finder.tags.map(navAnchor).join('')}</div></section><div class="marquee"><div>${[...home.marquee,...home.marquee].map(w=>`${esc(w)} <span>✳</span>`).join(' ')}</div></div><section class="quick-paths wrap" aria-label="${esc(home.quickPathsLabel)}">${home.quickPaths.map(p=>`<a href="${esc(p.url)}"><span>${esc(p.icon)}</span><div><strong>${esc(p.title)}</strong><small>${esc(p.text)}</small></div><b>↗</b></a>`).join('')}</section><section class="section wrap"><div class="section-title reveal"><div><span class="eyebrow">${esc(home.areas.eyebrow)}</span><h2>${headline(home.areas.headline)}</h2></div><p>${headline(home.areas.text)}</p></div><div class="areas-grid">${areas.map(a=>`<a class="area-card ${a.color} reveal" href="/cursos/?area=${a.id}"><span class="area-icon">${a.icon}</span><h3>${a.name}</h3><p>${a.description}</p><span class="area-bottom"><span>${courses.filter(c=>c.area===a.id).length} ${esc(home.areas.countLabel)}</span><span>↗</span></span></a>`).join('')}</div></section><section class="section soft-bg"><div class="wrap"><div class="section-title reveal"><div><span class="eyebrow">${esc(home.courses.eyebrow)}</span><h2>${headline(home.courses.headline)}</h2></div>${link(esc(home.courses.link.url),esc(home.courses.link.label),'text-link')}</div><div class="course-grid">${courses.filter(c=>c.featured).slice(0,3).map(courseCard).join('')}</div><p class="quiet-note">${esc(home.courses.note)}</p></div></section><section class="section wrap split-feature"><div class="split-photo reveal"><img src="/assets/student.webp" alt="${esc(home.split.photoAlt)}" loading="lazy"><span class="photo-label">${headline(home.split.photoLabel)} ↗</span></div><div class="reveal"><span class="eyebrow">${esc(home.split.eyebrow)}</span><h2>${headline(home.split.headline)}</h2><p>${esc(home.split.text)}</p><ul class="check-list">${home.split.items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul>${link(esc(home.split.link.url),esc(home.split.link.label),'text-link')}</div></section><section class="blue-band"><div class="wrap"><span class="eyebrow">${esc(home.band.eyebrow)}</span><h2>${renderHeadline(home.band.headline,esc,'span')}</h2><div class="steps-row">${home.band.steps.map(s=>`<div><span>${esc(s.number)}</span><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></div>`).join('')}</div>${link(esc(home.band.action.url),esc(home.band.action.label),'button white')}<span class="band-star" aria-hidden="true">✳</span></div></section><section class="section wrap"><div class="section-title"><div><span class="eyebrow">${esc(home.articles.eyebrow)}</span><h2>${headline(home.articles.headline)}</h2></div>${link(esc(home.articles.link.url),esc(home.articles.link.label),'text-link')}</div><div class="article-grid">${articles.slice(0,3).map(articleCard).join('')}</div></section>${cta()}`);
function articleCard(a){return `<article class="article-card reveal"><a href="/noticias/${a.id}/" tabindex="-1" aria-hidden="true"><img src="/assets/${a.image}.webp" alt="" loading="lazy"></a><span class="eyebrow">${a.category} · LEITURA DEMONSTRATIVA</span><h3><a href="/noticias/${a.id}/">${a.title}</a></h3><a class="text-link" href="/noticias/${a.id}/">Ler a história <span>↗</span></a></article>`}
const filters=`<aside class="filters" id="course-filters"><div class="filter-title"><h2>Filtrar cursos</h2><button type="button" id="clear-filters">Limpar</button></div><label>Área do conhecimento<select name="area" id="filter-area"><option value="">Todas as áreas</option>${areas.map(a=>`<option value="${a.id}">${a.name}</option>`).join('')}</select></label><label>Nível de formação<select name="nivel" id="filter-level"><option value="">Todas as formações</option><option>Licenciatura</option><option>Pós-graduação</option><option>Curso de curta duração</option></select></label><fieldset><legend>Modalidade</legend>${['Presencial','Online','Híbrido'].map(m=>`<label class="check-option"><input type="checkbox" name="mode" value="${m}">${m}</label>`).join('')}</fieldset><label>Turno<select name="turno" id="filter-shift"><option value="">Todos os turnos</option><option>Diurno</option><option>Pós-laboral</option><option>Flexível</option></select></label><label>Unidade<select name="unidade" id="filter-unit"><option value="">Todas as unidades</option><option>Campus Académico</option><option>Campus Digital</option></select></label><div class="filter-help"><span>Não sabe por onde começar?</span><p>Compare percursos e descubra o que combina consigo.</p><a href="/ingresso/">Orientação para ingresso ↗</a></div></aside>`;
write('/cursos/','Encontre o seu curso',`${crumb('Cursos')}${head('/cursos/')}<section class="wrap catalogue-section"><div class="catalogue-top"><form id="catalog-search" class="search-input"><span>⌕</span><label class="sr-only" for="catalog-q">Pesquisar cursos</label><input type="search" id="catalog-q" placeholder="Pesquise por curso, tema ou competência"><button class="button small">Pesquisar</button></form><a href="/favoritos/" class="outline-button">♡ Favoritos <span data-favorite-count>0</span></a><a href="/comparar/" class="outline-button">⇄ Comparar <span data-compare-count>0</span></a></div>${notice()}<div class="catalogue-mobile-tools"><button class="outline-button" id="toggle-filters" aria-expanded="false" aria-controls="course-filters"><span>☷</span> Filtros <b id="mobile-filter-count" hidden>0</b><span class="filter-chevron">⌄</span></button><span>Encontre o percurso certo para si.</span></div><div class="catalogue-layout">${filters}<div class="catalogue-results"><div class="results-heading"><p id="results-count" aria-live="polite">${courses.length} cursos para explorar</p><label>Ordenar por <select id="sort-courses"><option value="featured">Destaques</option><option value="az">Nome A–Z</option><option value="duration">Menor duração</option></select></label></div><div id="active-filters"></div><div class="course-grid two-cols" id="course-results">${courses.map(courseCard).join('')}</div><div id="no-courses" class="empty-state" hidden><span>⌕</span><h2>Nenhum curso encontrado.</h2><p>Experimente outra palavra ou remova alguns filtros.</p><button class="button" id="empty-clear">Limpar filtros <span>↗</span></button></div></div></div></section><div id="compare-bar" class="compare-bar" hidden><span><strong data-compare-count>0</strong> cursos seleccionados</span><a class="button small" href="/comparar/">Comparar agora ↗</a></div>`,{active:'catalog'});
for(const c of courses){const area=areas.find(a=>a.id===c.area);const specs=getCourseSpecs(c);write('/cursos/'+c.id+'/',c.name,`${crumb(c.name,'<a href="/cursos/">Cursos</a><span>/</span>')}<section class="course-hero wrap"><div><div class="eyebrow">${area.name} · ${c.level}</div><h1>${c.name}</h1><p>${c.description}</p><div class="course-hero-meta"><span>◷ ${c.duration}</span><span>◎ ${c.mode}</span><span>☷ ${c.shift}</span></div><div class="course-code">EXEMPLO DE FORMAÇÃO <span>•</span> ${c.level} <span>•</span> ${area.name}</div><div class="hero-buttons">${link('/candidatura/?curso='+c.id,'Experimentar candidatura')}<button class="outline-button" data-favorite="${c.id}" aria-pressed="false">♡ Guardar curso</button></div><p class="quiet-note">Curso demonstrativo · Não constitui oferta oficial.</p></div><div class="course-hero-image"><img src="/assets/${c.image}.webp" alt="Ambiente académico ilustrativo" fetchpriority="high"><span>${area.icon}</span></div></section><nav class="course-subnav" aria-label="Conteúdos do curso"><div class="wrap"><a href="#apresentacao">Apresentação</a><a href="#competencias">Competências</a><a href="#plano">Plano de estudos</a><a href="#carreiras">Possibilidades de actuação</a><a href="#ingresso">Ingresso</a></div></nav><section class="section wrap course-detail-layout"><div><section id="apresentacao" class="detail-block"><span class="eyebrow">UM PERCURSO DE DESCOBERTAS</span><h2>Conheça o universo de<br><em>${c.name}.</em></h2><p>${c.description} Este percurso ilustrativo liga fundamentos da área à análise de problemas, ao trabalho em equipa e à construção de projectos.</p><p>A proposta valoriza uma aprendizagem progressiva, a capacidade de investigar e a aplicação do conhecimento em diferentes contextos.</p>${notice(noticeFor('curso'))}</section><section id="competencias" class="detail-block course-competencies"><span class="eyebrow">DO CONHECIMENTO À PRÁTICA</span><h2>O que poderá desenvolver.</h2><p>Competências ilustrativas para ajudar a compreender a área.</p><ul class="competency-list">${specs.outcomes.map((item,i)=>`<li><span>0${i+1}</span><p>${item}</p><b aria-hidden="true">↗</b></li>`).join('')}</ul><div class="course-audience"><h3>É um caminho para si?</h3><p>${specs.audience}</p><span>Para começar</span><p>${specs.preparation}</p></div></section><section id="plano" class="detail-block"><span class="eyebrow">CONHECIMENTO EM CONSTRUÇÃO</span><h2>O que poderá explorar.</h2><p>Uma selecção ilustrativa de temas da área. Não corresponde a uma matriz curricular oficial.</p><div class="module-list">${c.modules.map((m,i)=>`<details${i===0?' open':''}><summary><span>0${i+1}</span>${m}<b>+</b></summary><p>${specs.modules[i].description}</p><span class="module-caption">Tema ilustrativo · Conteúdo sujeito a validação</span></details>`).join('')}</div></section><section class="detail-block course-method"><span class="eyebrow">UM PERCURSO COM ESTRUTURA</span><h2>Como poderá aprender.</h2><div class="method-grid"><article><span>◎</span><h3>Experiência de aprendizagem</h3><p>${specs.delivery} ${specs.practice}</p></article><article><span>✓</span><h3>Avaliação de exemplo</h3><p>${specs.assessment}</p></article></div><details class="resource-details"><summary>Recursos para a aprendizagem <span>+</span></summary><p>${specs.resources}</p><a class="text-link" href="/biblioteca/">Explorar a biblioteca ↗</a></details></section><section id="carreiras" class="detail-block"><span class="eyebrow">CONHECIMENTO QUE ABRE CAMINHOS</span><h2>Possibilidades de actuação.</h2><p>Exemplos de áreas relacionadas com a formação. O exercício profissional depende da habilitação, das regras e dos requisitos aplicáveis.</p><div class="career-tags">${c.careers.map(x=>`<span>↗ ${x}</span>`).join('')}</div></section><section id="ingresso" class="detail-block"><h2>Prepare a sua candidatura.</h2><p>Consulte o edital oficial e confirme habilitações exigidas, documentos, provas, vagas e calendário junto da instituição.</p>${link('/ingresso/','Conhecer as formas de ingresso','text-link')}<div class="entry-requirement"><span>▤</span><div><h3>Preparação de acesso</h3><p>${specs.access} Documentos, provas, taxas e prazos dependem do edital oficial.</p></div></div></section><section class="detail-block course-questions"><h2>Antes de escolher.</h2><div class="faq-list"><details><summary>O plano de estudos é oficial?<span>+</span></summary><p>Não. Estes temas mostram como o curso poderá ser apresentado. Matriz curricular, carga horária, créditos e qualificação final precisam de validação pelo {{SCHOOL}}.</p></details><details><summary>Posso guardar esta informação?<span>+</span></summary><p>Sim. Pode guardar o curso nos favoritos, compará-lo com outros percursos ou descarregar uma ficha demonstrativa. Os favoritos ficam neste navegador.</p></details><details><summary>Como confirmar propinas, vagas e requisitos?<span>+</span></summary><p>Consulte o edital e os contactos oficiais da instituição. Esta prévia não anuncia vagas nem valores confirmados.</p></details></div></section></div><aside class="course-summary"><span class="eyebrow">O PERCURSO, NUM RELANCE</span><h3>${c.name}</h3><dl>${[['Formação',c.level],['Duração ilustrativa',c.duration],['Estrutura',specs.structure],['Idioma de exemplo',specs.language],['Modalidade',c.mode],['Turno',c.shift],['Unidade de exemplo',c.unit],['Propinas','A confirmar'],['Vagas e calendário','A confirmar']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>${link('/candidatura/?curso='+c.id,'Explorar candidatura')}<button class="course-guide-button outline-button" data-course-guide="${c.id}">Descarregar ficha de exemplo <span>↓</span></button><label class="compare-label"><input type="checkbox" data-compare="${c.id}"> Adicionar à comparação</label><a href="/contactos/">Tem alguma dúvida? Prepare uma mensagem ↗</a></aside></section><aside class="course-mobile-action" data-course-action hidden aria-label="Atalho de candidatura"><div><small>CURSO DEMONSTRATIVO</small><strong>${c.name}</strong></div>${link('/candidatura/?curso='+c.id,'Candidatura','button small')}</aside><section class="section soft-bg"><div class="wrap"><div class="section-title"><div><span class="eyebrow">CONTINUE A DESCOBRIR</span><h2>Outros caminhos possíveis.</h2></div>${link('/cursos/','Ver catálogo','text-link')}</div><div class="course-grid">${courses.filter(x=>x.id!==c.id).sort((a,b)=>Number(b.area===c.area)-Number(a.area===c.area)).slice(0,3).map(courseCard).join('')}</div></div></section>`,{active:'course'})}
write('/favoritos/','Os meus cursos favoritos',`${crumb('Favoritos')}${head('/favoritos/')}<section class="wrap section"><div class="course-grid" id="saved-courses"></div><div id="saved-empty" class="empty-state"><span>♡</span><h2>O seu próximo favorito está por descobrir.</h2><p>Toque no coração de um curso para o guardar aqui.</p>${link('/cursos/','Explorar cursos')}</div></section>`,{active:'favorites'});
write('/comparar/','Comparar cursos',`${crumb('Comparar cursos')}${head('/comparar/')}<section class="wrap section"><div id="comparison"></div><div class="compare-add"><label for="compare-add">Adicionar um curso</label><div><select id="compare-add"><option value="">Seleccione um curso</option>${courses.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select><button id="add-comparison" class="button small">Adicionar <span>+</span></button></div></div></section>`,{active:'compare'});
write('/ingresso/','Como candidatar-se',`${crumb('Ingresso')}${head('/ingresso/',link('/candidatura/','Experimentar candidatura'))}<section class="wrap section"><div class="section-title"><div><span class="eyebrow">UM PERCURSO, DIFERENTES PONTOS DE PARTIDA</span><h2>Como quer <em>começar?</em></h2></div><p>Orientações gerais de ingresso.<br>Os critérios oficiais dependem do edital do {{SCHOOL}}.</p></div><div class="info-grid">${[['01','Primeiro ingresso','Para quem pretende iniciar a primeira formação superior. Confirme as habilitações exigidas, as provas de acesso e o calendário.','Primeiro ingresso'],['02','Transferência','Para quem já frequenta uma instituição e pretende conhecer as condições de transferência e eventual equivalência.','Transferência'],['03','Segunda formação','Para quem já concluiu uma formação superior e procura um novo percurso. Confirme os procedimentos e a documentação.','Segunda formação']].map(s=>`<article class="info-card"><span class="big-number">${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p>${link(s[3]==='Transferência'?'/percursos-de-ingresso/':'/candidatura/?via='+encodeURIComponent(s[3]),'Explorar esta opção','text-link')}</article>`).join('')}</div>${notice(noticeFor('ingresso'))}</section><section class="soft-bg section"><div class="wrap split-text"><div><span class="eyebrow">ORGANIZE O PRÓXIMO PASSO</span><h2>Uma pequena lista.<br><em>Uma grande ajuda.</em></h2><p>Use a lista para preparar uma candidatura real. Confirme todos os requisitos nos canais institucionais.</p>${link('/preparar-candidatura/','Abrir a minha lista de preparação','text-link')}</div><ol class="numbered-list"><li><span>01</span><div><h3>Encontre a sua área</h3><p>Conheça o curso, a formação e as possibilidades.</p></div></li><li><span>02</span><div><h3>Leia as regras oficiais</h3><p>Verifique requisitos, documentação, provas e prazos.</p></div></li><li><span>03</span><div><h3>Prepare a documentação</h3><p>Tenha identificação e comprovativos de habilitações válidos.</p></div></li><li><span>04</span><div><h3>Reveja e acompanhe</h3><p>Use apenas os canais oficiais para concluir a candidatura real.</p></div></li></ol></div></section>${cta()}`);
write('/candidatura/','Candidatura online',`${crumb('Candidatura')}${head('/candidatura/')}<section class="wrap section application-layout"><aside class="application-aside"><span class="eyebrow">A SUA CANDIDATURA</span><ol class="wizard-steps"><li class="current" data-step-label="1"><span>1</span><div><strong>Escolha do curso</strong><small>O que quer aprender</small></div></li><li data-step-label="2"><span>2</span><div><strong>O seu perfil</strong><small>Informações de exemplo</small></div></li><li data-step-label="3"><span>3</span><div><strong>Rever e concluir</strong><small>Confirme cada detalhe</small></div></li></ol><div class="application-help"><h3>Ao seu ritmo.</h3><p>O rascunho é guardado apenas neste dispositivo. Esta candidatura é uma simulação e não é enviada à instituição.</p><a href="/ajuda/">Precisa de orientação? ↗</a></div></aside><div class="application-form"><div class="wizard-progress" aria-hidden="true"><span id="wizard-progress-bar"></span></div>${notice(noticeFor('candidatura'))}<div id="draft-prompt" hidden></div><form id="application-form"><section data-step="1"><div class="step-heading"><span class="eyebrow">PASSO 01 DE 03</span><h2>Encontre a sua direcção.</h2><p>Seleccione o curso e o seu ponto de partida.</p></div><label>Curso de interesse <span>*</span><select id="apply-course" name="course" required><option value="">Seleccione um curso</option>${courses.map(c=>`<option value="${c.id}">${c.name} · ${c.level}</option>`).join('')}</select></label><div id="apply-course-info"></div><div class="form-row"><label>Forma de ingresso <span>*</span><select name="via" required><option value="">Seleccione</option><option>Primeiro ingresso</option><option>Transferência</option><option>Segunda formação</option><option>Formação contínua</option></select></label><label>Período de interesse <span>*</span><select name="period" required><option value="">Seleccione</option><option>Próximo período disponível</option><option>Quero apenas conhecer as opções</option></select></label></div></section><section data-step="2" hidden><div class="step-heading"><span class="eyebrow">PASSO 02 DE 03</span><h2>Conte-nos um pouco sobre si.</h2><p>Preencha com informações fictícias para experimentar o percurso.</p></div><label>Nome de exemplo <span>*</span><input name="name" required maxlength="100" autocomplete="off" placeholder="Ex.: Joana Exemplo"></label><div class="form-row"><label>E-mail de exemplo <span>*</span><input name="email" type="email" required maxlength="150" autocomplete="off" placeholder="joana@example.com"></label><label>Província de interesse <span>*</span><select name="province" required><option value="">Seleccione</option>${['Benguela','Bengo','Bié','Cabinda','Cuando','Cubango','Cuanza Norte','Cuanza Sul','Cunene','Huambo','Huíla','Icolo e Bengo','Luanda','Lunda Norte','Lunda Sul','Malanje','Moxico','Moxico Leste','Namibe','Uíge','Zaire','Outra / prefiro não indicar'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><label>O que o motiva a explorar este curso?<textarea name="motivation" maxlength="1000" rows="4" placeholder="Partilhe uma ideia ou um objectivo (opcional)"></textarea></label><div class="checklist-box"><h3>Preparação para uma candidatura real</h3><p>Não faça upload de documentos nesta prévia. Numa candidatura oficial, confirme a lista de requisitos com a instituição.</p><label class="check-option"><input type="checkbox" name="checkId"> Sei que devo confirmar os documentos de identificação exigidos.</label><label class="check-option"><input type="checkbox" name="checkSchool"> Sei que devo confirmar os comprovativos de habilitações.</label></div></section><section data-step="3" hidden><div class="step-heading"><span class="eyebrow">PASSO 03 DE 03</span><h2>O próximo passo, com clareza.</h2><p>Reveja os seus dados antes de concluir a demonstração.</p></div><div id="application-review" class="review-card"></div><label class="check-option consent"><input type="checkbox" name="consent" required> Compreendo que esta candidatura é demonstrativa, fica guardada apenas neste navegador e não é enviada ao {{SCHOOL}}.</label></section><p id="application-error" class="form-error" role="alert"></p><div class="form-controls"><button type="button" class="text-button" id="wizard-back" hidden>← Voltar</button><button type="button" class="text-button" id="save-draft">Guardar rascunho</button><button type="submit" class="button" id="wizard-next">Continuar <span>→</span></button></div></form><div id="application-success" hidden class="success-panel"></div></div></section>`,{active:'application'});
write('/candidaturas/','Acompanhar candidaturas',`${crumb('Área do candidato')}${head('/candidaturas/')}<section class="section wrap">${notice(noticeFor('candidaturas'))}<div id="candidate-records"></div><div class="section-title top-space"><div><h2>Continuar a descobrir.</h2><p>A sua escolha merece tempo e perspectiva.</p></div>${link('/cursos/','Explorar cursos','text-link')}</div></section>`,{active:'candidates'});
write('/login/','Entrar no portal',`${crumb('Acesso ao portal')}<section class="login-layout wrap section"><div class="login-story"><span class="eyebrow">UM LUGAR PARA A SUA JORNADA</span><h1>O seu campus.<br><em>Mais perto de si.</em></h1><p>Disciplinas, horários, candidaturas e serviços. Uma visão organizada da experiência académica.</p><img src="/assets/hero.webp" alt="Estudantes a colaborar na biblioteca"><span class="login-star">✳</span></div><div class="login-card"><div class="login-icon">◫</div><h2>Bem-vindo ao {{SCHOOL}}.</h2><p>Escolha como quer explorar a experiência.</p><a class="button auth-button" href="/signin-with-chatgpt?return_to=%2Fportal%2F" target="_top">Entrar com ChatGPT <span>↗</span></a><p class="input-hint">Acesso seguro da hospedagem. Não utilize uma senha institucional nesta prévia.</p><div class="or"><span>ou explore a experiência</span></div><a class="outline-button demo-login" href="/portal/">Explorar portal demonstrativo <span>→</span></a><div class="login-note"><span>ⓘ</span><p>O portal contém um perfil fictício e dados académicos de exemplo. Não há ligação ao sistema do {{SCHOOL}}.</p></div><div class="login-bottom"><a href="/candidaturas/">Sou candidato</a><a href="/ajuda/">Preciso de ajuda ↗</a></div></div></section>`,{active:'login'});
// Institutional and student-service pages.
const sobre=pagina('sobre');
write('/sobre/',sobre.title,`${crumb(sobre.crumb)}${head('/sobre/')}<section class="wrap section split-feature"><div class="split-photo"><img src="/assets/campus.webp" alt="${esc(sobre.split.photoAlt)}"><span class="photo-label">${headline(sobre.split.photoLabel)} ↗</span></div><div><span class="eyebrow">${esc(sobre.split.eyebrow)}</span><h2>${headline(sobre.split.headline)}</h2>${sobre.split.paragraphs.map(t=>`<p>${esc(t)}</p>`).join('')}${link(esc(sobre.split.link.url),esc(sobre.split.link.label),'text-link')}</div></section><section class="section soft-bg"><div class="wrap"><div class="section-title"><h2>${headline(sobre.ideas.headline)}</h2></div><div class="info-grid">${sobre.ideas.items.map(x=>`<article class="info-card"><span class="area-icon">${esc(x.icon)}</span><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></article>`).join('')}</div></div></section>${cta()}`);
const vida=pagina('vida-academica');
write('/vida-academica/',vida.title,`${crumb(vida.crumb)}${head('/vida-academica/')}<section class="section wrap"><div class="editorial-image"><img src="/assets/community.webp" alt="${esc(vida.photoAlt)}"><span>${esc(vida.photoLabel)} ↗</span></div><div class="info-grid top-space">${vida.items.map(x=>`<article class="info-card"><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p>${link(esc(x.link.url),esc(x.link.label),'text-link')}</article>`).join('')}</div></section><section class="soft-bg section"><div class="wrap"><div class="section-title"><h2>${headline(vida.articles.headline)}</h2></div><div class="article-grid">${articleList(vida.articles.ids).map(articleCard).join('')}</div></div></section>${cta()}`);
const campus=pagina('campus');
write('/campus/',campus.title,`${crumb(campus.crumb)}${head('/campus/')}<section class="section wrap">${notice(noticeFor('campus'))}<div class="space-grid">${campus.spaces.map(x=>`<article><img src="/assets/${esc(x.image)}.webp" alt="${esc(x.title)} ${esc(campus.altSuffix)}" loading="lazy"><h2>${esc(x.title)}</h2><p>${esc(x.text)}</p></article>`).join('')}</div></section>${cta()}`);
const servicos=pagina('servicos');
write('/servicos/',servicos.title,`${crumb(servicos.crumb)}${head('/servicos/')}<section class="wrap section"><div class="service-intro"><div><span class="eyebrow">${esc(servicos.eyebrow)}</span><h2>${headline(servicos.headline)}</h2></div><p>${headline(servicos.text)}</p></div><div class="service-grid">${services.map(s=>`<a class="service-card" href="${s.url}"><span>${s.icon}</span><h2>${s.title}</h2><p>${s.text}</p><b>${esc(servicos.cardLabel)} ↗</b></a>`).join('')}</div></section>${cta()}`);
const simplePages=loadSimplePages();
// As cinco páginas de serviço partilham a mesma forma. O bloco `resources` é
// opcional e substitui o antigo caso especial de /bolsas/ no gerador: a agência
// de bolsas do país é conteúdo da escola, não uma excepção escrita em código.
for(const page of simplePages.pages)write(page.url,page.title,`${crumb(page.title)}${pageHead(esc(page.eyebrow),headline(page.headline),esc(page.description))}<section class="wrap section"><div class="section-title"><h2>${esc(page.sectionTitle)}</h2></div><div class="info-grid">${page.items.map((x,i)=>`<article class="info-card"><span class="big-number">0${i+1}</span><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></article>`).join('')}</div><div class="inline-cta"><p>${esc(simplePages.inlineCta)}</p>${link(esc(page.action.url),esc(page.action.label))}</div>${page.resources?`${link(esc(page.resources.secondary.url),esc(page.resources.secondary.label),'text-link')}<p class="resource-link">${esc(page.resources.prefix)} ${page.resources.links.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.label)} ↗</a>`).join('')}</p>${notice(esc(page.resources.notice))}`:''}</section>${cta()}`);
write('/biblioteca/','Biblioteca e recursos',`${crumb('Biblioteca')}${head('/biblioteca/')}<section class="section wrap"><div class="section-title"><h2>Abra uma nova<br><em>janela de conhecimento.</em></h2><p>Recursos externos de acesso público.<br>A disponibilidade depende de cada plataforma.</p></div><div class="resource-grid">${[['DOAJ','Artigos científicos','Directório de revistas de acesso aberto em diversas áreas.','https://doaj.org/','▤'],['SciELO','Investigação em acesso aberto','Biblioteca de publicações científicas, incluindo conteúdos em português.','https://scielo.org/','◎'],['MIT OpenCourseWare','Materiais de aprendizagem','Recursos de disciplinas e materiais de estudo disponibilizados pelo MIT.','https://ocw.mit.edu/','⌘'],['OpenStax','Livros e fundamentos','Livros de estudo abertos para explorar conceitos de diferentes áreas.','https://openstax.org/','▥']].map(x=>`<article class="resource-card"><span>${x[4]}</span><div class="eyebrow">${x[1]}</div><h2>${x[0]}</h2><p>${x[2]}</p><a class="text-link" href="${x[3]}" target="_blank" rel="noopener">Explorar recurso <span>↗</span></a></article>`).join('')}</div><div class="study-guide"><h2>Antes de citar, investigue a fonte.</h2><p>Verifique autoria, data, método e contexto. Distinga opinião de evidência e consulte as orientações de referência bibliográfica do seu curso.</p>${link('/noticias/organizar-rotina/','Organizar a rotina de estudo','text-link')}</div></section>`);
function eventCard(e){return `<article class="event-card"><div class="date-block"><strong><time datetime="${e.date}">${e.day}</time></strong><span>${e.month}</span></div><div><span class="eyebrow">${e.category} · EVENTO ILUSTRATIVO</span><h3>${e.title}</h3><p>${e.description}</p><div class="event-meta"><span>◷ ${e.time}</span><span>◎ ${e.place}</span></div></div><button class="outline-button" data-calendar="${e.id}" aria-label="Descarregar ${esc(e.title)} para a agenda — evento demonstrativo">Guardar na agenda <span>↗</span></button></article>`}
for(const url of ['/eventos/','/calendario/'])write(url,url==='/eventos/'?'Eventos':'Calendário académico',`${crumb(url==='/eventos/'?'Eventos':'Calendário')}${head(url)}<section class="wrap section">${notice(noticeFor('agenda'))}<div class="calendar-heading"><h2>Novembro de 2026</h2><span class="tag">Fuso horário de {{COUNTRY}} · WAT (UTC+1)</span></div><div class="events-list">${events.map(eventCard).join('')}</div></section>`);
write('/noticias/','Notícias e histórias',`${crumb('Notícias')}${head('/noticias/')}<section class="section wrap"><div class="article-grid">${articles.map(articleCard).join('')}</div></section>`);
for(const a of articles)write('/noticias/'+a.id+'/',a.title,`${crumb(a.category,'<a href="/noticias/">Notícias</a><span>/</span>')}<article class="article-detail wrap"><header class="article-header"><span class="eyebrow">${a.category} · CONTEÚDO EDITORIAL DEMONSTRATIVO</span><h1>${a.title}</h1><p>${a.intro}</p><span class="article-byline">Redacção do projecto · <time datetime="2026-10-20">20 de Outubro de 2026</time> · 3 min de leitura</span></header><img class="article-cover" src="/assets/${a.image}.webp" alt="Ambiente académico ilustrativo"><div class="article-text">${a.sections.map(s=>`<section><h2>${s[0]}</h2><p>${s[1]}</p></section>`).join('')}<div class="article-share"><button class="outline-button" data-copy-link>Copiar link <span>↗</span></button>${link('/noticias/','Continuar a ler','text-link')}</div></div></article>${cta()}`);
